PRAGMA foreign_keys=ON;
CREATE TABLE members(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,google_sub TEXT UNIQUE,nickname TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),expires_at INTEGER NOT NULL);
CREATE TABLE oauth_states(id TEXT PRIMARY KEY,verifier TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE characters(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES members(id),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),alias TEXT NOT NULL DEFAULT '',faction TEXT NOT NULL CHECK(faction IN ('mage','templar')),age TEXT NOT NULL DEFAULT '',gender TEXT NOT NULL DEFAULT '',race TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT '',position TEXT NOT NULL DEFAULT '',personality TEXT NOT NULL DEFAULT '',background TEXT NOT NULL DEFAULT '',goals TEXT NOT NULL DEFAULT '',secrets TEXT NOT NULL DEFAULT '',extra TEXT NOT NULL DEFAULT '{}',image_path TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE affection(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES characters(id),target_id TEXT NOT NULL REFERENCES characters(id),value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 100 AND value%5=0),note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(source_id,target_id),CHECK(source_id<>target_id));
CREATE TABLE relationships(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES characters(id),target_id TEXT NOT NULL REFERENCES characters(id),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),kind TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',directed INTEGER NOT NULL DEFAULT 0 CHECK(directed IN (0,1)),status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1,CHECK(source_id<>target_id));
CREATE TABLE posts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES members(id),character_id TEXT REFERENCES characters(id),category TEXT NOT NULL CHECK(category IN ('story','art','notice')),title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200),body TEXT NOT NULL DEFAULT '',character_ids TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE comments(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES members(id),character_id TEXT REFERENCES characters(id),target_id TEXT REFERENCES characters(id),post_id TEXT REFERENCES posts(id),parent_id TEXT REFERENCES comments(id),body TEXT NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 20000),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1,CHECK((target_id IS NOT NULL)+(post_id IS NOT NULL)=1));
CREATE TABLE media(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES members(id),character_id TEXT REFERENCES characters(id),post_id TEXT REFERENCES posts(id),path TEXT NOT NULL UNIQUE,caption TEXT NOT NULL DEFAULT '',bytes INTEGER NOT NULL CHECK(bytes BETWEEN 1 AND 10485760),mime TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE uploads(path TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES members(id),bytes INTEGER NOT NULL,mime TEXT NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE history(id TEXT PRIMARY KEY,table_name TEXT NOT NULL,record_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,before_json TEXT,after_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE backup_runs(id TEXT PRIMARY KEY,status TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX idx_characters_owner ON characters(owner_id);
CREATE INDEX idx_relationship_status ON relationships(status,source_id,target_id);
CREATE INDEX idx_comment_target ON comments(target_id,post_id,parent_id);
CREATE INDEX idx_media_links ON media(character_id,post_id);
CREATE INDEX idx_session_expiry ON sessions(expires_at);
